import React, { useState, useEffect } from 'react';
import { useTheme } from '../context/ThemeContext';
import { supabase } from '../utils/supabase';

export default function Analytics({ user, onUpgrade }) {
  const { t } = useTheme();
  const [stats, setStats] = useState({
    totalGenerated: 0,
    totalPosts: 0,
    totalLikes: 0,
    totalFollowers: 0,
    totalFollowing: 0,
  });
  const [platformBreakdown, setPlatformBreakdown] = useState([]);
  const [recentContent, setRecentContent] = useState([]);
  const [activityData, setActivityData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isPro, setIsPro] = useState(false);

  useEffect(() => {
    checkPlan();
    fetchAnalytics();
  }, []);

  const checkPlan = async () => {
    // Check if user has Masterpiece plan
    // For now check profiles rank or just show for all — can gate later
    setIsPro(true); // Show for all users for demo; gate with Stripe later
  };

  const fetchAnalytics = async () => {
    setLoading(true);
    try {
      // Total content generated
      const { count: generatedCount } = await supabase
        .from('generated_outputs')
        .select('*', { count: 'exact', head: true })
        .eq('user_id', user?.id);

      // Total canvas posts
      const { count: postsCount } = await supabase
        .from('canvas_posts')
        .select('*', { count: 'exact', head: true })
        .eq('user_id', user?.id);

      // Total likes received on canvas posts
      const { data: userPosts } = await supabase
        .from('canvas_posts')
        .select('likes, platform, content, created_at')
        .eq('user_id', user?.id)
        .order('created_at', { ascending: false });

      const totalLikes = (userPosts || []).reduce((sum, p) => sum + (p.likes || 0), 0);

      // Platform breakdown
      const platformMap = {};
      (userPosts || []).forEach(p => {
        if (p.platform) {
          platformMap[p.platform] = (platformMap[p.platform] || 0) + 1;
        }
      });
      const platformData = Object.entries(platformMap).map(([platform, count]) => ({
        platform, count,
        percent: Math.round((count / (userPosts?.length || 1)) * 100)
      })).sort((a, b) => b.count - a.count);

      // Followers count
      const { count: followersCount } = await supabase
        .from('followers')
        .select('*', { count: 'exact', head: true })
        .eq('following_id', user?.id);

      const { count: followingCount } = await supabase
        .from('followers')
        .select('*', { count: 'exact', head: true })
        .eq('follower_id', user?.id);

      // Recent generated content
      const { data: recentGen } = await supabase
        .from('generated_outputs')
        .select('*')
        .eq('user_id', user?.id)
        .order('created_at', { ascending: false })
        .limit(5);

      // Activity last 7 days
      const last7Days = Array.from({ length: 7 }, (_, i) => {
        const d = new Date();
        d.setDate(d.getDate() - (6 - i));
        return {
          label: d.toLocaleDateString('en', { weekday: 'short' }),
          date: d.toISOString().split('T')[0],
          posts: 0,
          generated: 0
        };
      });

      (userPosts || []).forEach(p => {
        const date = p.created_at?.split('T')[0];
        const day = last7Days.find(d => d.date === date);
        if (day) day.posts++;
      });

      (recentGen || []).forEach(g => {
        const date = g.created_at?.split('T')[0];
        const day = last7Days.find(d => d.date === date);
        if (day) day.generated++;
      });

      setStats({
        totalGenerated: generatedCount || 0,
        totalPosts: postsCount || 0,
        totalLikes,
        totalFollowers: followersCount || 0,
        totalFollowing: followingCount || 0,
      });
      setPlatformBreakdown(platformData);
      setRecentContent(recentGen || []);
      setActivityData(last7Days);

    } catch (err) {
      console.log('Analytics error:', err);
    }
    setLoading(false);
  };

  const platformColors = {
    LinkedIn: '#0a66c2', Twitter: '#1d9bf0',
    Instagram: '#e1306c', YouTube: '#ff0000', Blog: '#22c55e'
  };

  const formatTime = (timestamp) => {
    if (!timestamp) return '';
    const diff = Date.now() - new Date(timestamp).getTime();
    const hours = Math.floor(diff / 3600000);
    const days = Math.floor(diff / 86400000);
    if (hours < 1) return 'just now';
    if (hours < 24) return `${hours}h ago`;
    return `${days}d ago`;
  };

  const maxActivity = Math.max(...activityData.map(d => d.posts + d.generated), 1);

  if (loading) return (
    <div style={{ textAlign: 'center', padding: '80px', color: t.textMuted }}>
      <p style={{ fontSize: '32px', marginBottom: '12px' }}>📊</p>
      <p>Loading analytics...</p>
    </div>
  );

  return (
    <div>
      {/* Header */}
      <div style={{ marginBottom: '28px' }}>
        <h1 style={{ color: t.textPrimary, fontSize: '32px', fontWeight: 700, margin: '0 0 6px' }}>
          Analytics
        </h1>
        <p style={{ color: t.textSecondary, fontSize: '15px', margin: 0 }}>
          Your content performance and growth overview
        </p>
      </div>

      {/* Stats Grid */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: '12px', marginBottom: '20px' }}>
        {[
          { label: 'Generated', value: stats.totalGenerated, icon: '⚡', color: t.accent },
          { label: 'Canvas Posts', value: stats.totalPosts, icon: '✍️', color: '#8b5cf6' },
          { label: 'Likes Received', value: stats.totalLikes, icon: '❤️', color: '#ef4444' },
          { label: 'Followers', value: stats.totalFollowers, icon: '👥', color: '#22c55e' },
          { label: 'Following', value: stats.totalFollowing, icon: '➕', color: '#f59e0b' },
        ].map(stat => (
          <div key={stat.label} style={{
            background: t.bgCard, border: `1px solid ${t.border}`,
            borderRadius: '12px', padding: '16px', boxShadow: t.shadowCard,
            borderTop: `3px solid ${stat.color}`
          }}>
            <span style={{ fontSize: '20px' }}>{stat.icon}</span>
            <p style={{ color: t.textPrimary, fontSize: '28px', fontWeight: 700, margin: '8px 0 2px' }}>
              {stat.value}
            </p>
            <p style={{ color: t.textMuted, fontSize: '11px', margin: 0 }}>{stat.label}</p>
          </div>
        ))}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px', marginBottom: '16px' }}>

        {/* Activity Chart — last 7 days */}
        <div style={{
          background: t.bgCard, border: `1px solid ${t.border}`,
          borderRadius: '12px', padding: '20px', boxShadow: t.shadowCard
        }}>
          <h3 style={{ color: t.textPrimary, fontSize: '14px', fontWeight: 600, margin: '0 0 4px' }}>
            Activity — Last 7 Days
          </h3>
          <p style={{ color: t.textMuted, fontSize: '12px', margin: '0 0 20px' }}>
            Posts + generations per day
          </p>
          <div style={{ display: 'flex', alignItems: 'flex-end', gap: '8px', height: '120px' }}>
            {activityData.map((day, i) => {
              const total = day.posts + day.generated;
              const height = Math.max((total / maxActivity) * 100, 4);
              return (
                <div key={i} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '6px' }}>
                  <span style={{ color: t.textMuted, fontSize: '10px' }}>{total || ''}</span>
                  <div style={{ width: '100%', display: 'flex', flexDirection: 'column', gap: '2px', alignItems: 'center' }}>
                    {/* Generated bar */}
                    {day.generated > 0 && (
                      <div style={{
                        width: '80%', height: `${(day.generated / maxActivity) * 80}px`,
                        background: t.accent, borderRadius: '3px 3px 0 0',
                        minHeight: '4px'
                      }} title={`${day.generated} generated`} />
                    )}
                    {/* Posts bar */}
                    <div style={{
                      width: '80%', height: `${(day.posts / maxActivity) * 80}px`,
                      background: '#8b5cf6', borderRadius: day.generated > 0 ? '0' : '3px 3px 0 0',
                      minHeight: total > 0 ? '4px' : '2px',
                      opacity: total > 0 ? 1 : 0.2
                    }} title={`${day.posts} posts`} />
                  </div>
                  <span style={{ color: t.textMuted, fontSize: '10px' }}>{day.label}</span>
                </div>
              );
            })}
          </div>
          <div style={{ display: 'flex', gap: '16px', marginTop: '12px' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
              <div style={{ width: '10px', height: '10px', borderRadius: '2px', background: t.accent }} />
              <span style={{ color: t.textMuted, fontSize: '11px' }}>Generated</span>
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
              <div style={{ width: '10px', height: '10px', borderRadius: '2px', background: '#8b5cf6' }} />
              <span style={{ color: t.textMuted, fontSize: '11px' }}>Canvas Posts</span>
            </div>
          </div>
        </div>

        {/* Platform Breakdown */}
        <div style={{
          background: t.bgCard, border: `1px solid ${t.border}`,
          borderRadius: '12px', padding: '20px', boxShadow: t.shadowCard
        }}>
          <h3 style={{ color: t.textPrimary, fontSize: '14px', fontWeight: 600, margin: '0 0 4px' }}>
            Platform Breakdown
          </h3>
          <p style={{ color: t.textMuted, fontSize: '12px', margin: '0 0 20px' }}>
            Your posts by platform
          </p>
          {platformBreakdown.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '30px', color: t.textMuted, fontSize: '13px' }}>
              No posts yet — start sharing on Canvas!
            </div>
          ) : (
            platformBreakdown.map(p => (
              <div key={p.platform} style={{ marginBottom: '14px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '5px' }}>
                  <span style={{ color: t.textPrimary, fontSize: '13px', fontWeight: 500 }}>{p.platform}</span>
                  <span style={{ color: t.textMuted, fontSize: '12px' }}>{p.count} posts · {p.percent}%</span>
                </div>
                <div style={{ height: '6px', background: t.bgSecondary, borderRadius: '3px', overflow: 'hidden' }}>
                  <div style={{
                    height: '100%', width: `${p.percent}%`,
                    background: platformColors[p.platform] || t.accent,
                    borderRadius: '3px', transition: 'width 0.5s ease'
                  }} />
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Recent Generated Content */}
      <div style={{
        background: t.bgCard, border: `1px solid ${t.border}`,
        borderRadius: '12px', padding: '20px', boxShadow: t.shadowCard
      }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
          <div>
            <h3 style={{ color: t.textPrimary, fontSize: '14px', fontWeight: 600, margin: '0 0 2px' }}>
              Recent Generations
            </h3>
            <p style={{ color: t.textMuted, fontSize: '12px', margin: 0 }}>Your last 5 AI-generated pieces</p>
          </div>
          <span style={{
            padding: '3px 10px', borderRadius: '20px', fontSize: '11px',
            background: t.accentSubtle, color: t.accent, border: `1px solid ${t.accent}44`
          }}>
            {stats.totalGenerated} total
          </span>
        </div>

        {recentContent.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '30px', border: `1px dashed ${t.border}`, borderRadius: '8px' }}>
            <p style={{ color: t.textMuted, fontSize: '13px' }}>No content generated yet</p>
          </div>
        ) : (
          recentContent.map((item, i) => (
            <div key={item.id || i} style={{
              padding: '12px 14px', background: t.bgSecondary,
              borderRadius: '8px', marginBottom: '8px',
              border: `1px solid ${t.border}`
            }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '4px' }}>
                <span style={{ color: t.accent, fontSize: '11px', fontWeight: 600 }}>
                  {item.platform || 'General'} · {item.tone || ''}
                </span>
                <span style={{ color: t.textMuted, fontSize: '11px' }}>
                  {formatTime(item.created_at)}
                </span>
              </div>
              <p style={{
                color: t.textPrimary, fontSize: '13px', margin: 0,
                overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap'
              }}>
                {item.output || item.content || 'Generated content'}
              </p>
            </div>
          ))
        )}
      </div>
    </div>
  );
}
